// Generated by tools/export_atlas.py from the reviewed local atlas.
const mounted=new WeakMap();
export function renderAtlas(root){
  if(mounted.has(root))return mounted.get(root);
  const job=loadAtlas(root);mounted.set(root,job);return job;
}
async function loadAtlas(root){
  root.setAttribute('aria-busy','true');root.innerHTML='<p class="note" role="status">Cargando mapa temático…</p>';
  try{
    const response=await fetch(new URL('../data/atlas.json',import.meta.url));
    if(!response.ok)throw new Error('Atlas no disponible');
    const data=await response.json();
    if(!Array.isArray(data.rows)||data.points.length!==data.rows.length)throw new Error('Atlas incompleto');
    root.innerHTML="<section class=\"intro\"><div><div class=\"eyebrow\">Una geografía de las ideas · proyectos de ley</div><h2>Atlas de proyectos</h2><p>Recorré los temas que acercan a los proyectos de ley y descubrí quiénes los trabajan, aunque no firmen juntos.</p><p class=\"atlas-cut\">Atlas experimental · 2.206 proyectos de ley · corte 14/10/2026.</p></div><div class=\"passport\"><div>CUADERNO DE VIAJE<br><strong id=\"atlas-visited\">0 / 10</strong><br>ZONAS EXPLORADAS</div></div></section>\n<div class=\"toolbar section-tools\"><label>Viajar a una zona<select id=\"atlas-zone\"><option value=\"\">Todo el atlas</option></select></label><label class=\"person\">Iluminar proyectos de<select id=\"atlas-person\"><option value=\"\">Todos los legisladores</option></select></label><label class=\"check\"><input type=\"checkbox\" id=\"atlas-coauthors\">Incluir coautorías</label><label class=\"check\"><input type=\"checkbox\" id=\"atlas-labels\" checked>Ver nombres</label></div>\n<div class=\"layout\"><section><div class=\"map-wrap\"><svg id=\"atlas-map\" viewBox=\"0 0 1080 840\" role=\"group\" aria-label=\"Atlas temático interactivo. También podés elegir una zona o buscar un proyecto con los controles.\"></svg><div class=\"map-tools\"><button id=\"atlas-plus\" aria-label=\"Acercar mapa\">+</button><button id=\"atlas-minus\" aria-label=\"Alejar mapa\">−</button><button id=\"atlas-reset\">Ver todo ↺</button></div><div class=\"hint\">Arrastrá para recorrer · + / − para acercar</div><div class=\"map-index\"><b>2.206 proyectos de ley</b><br>DIC. 2023 — OCT. 2026 · SIN ESCALA GEOGRÁFICA</div></div><div class=\"key\"><span><i></i>Proyecto</span><span class=\"author\"><i></i>Legislador seleccionado</span><span class=\"selected-key\"><i></i>Proyecto seleccionado</span><span id=\"atlas-person-count\" role=\"status\"></span></div><p class=\"map-note\">La costa y el relieve son ilustrativos. Los nombres orientan: no son categorías oficiales ni fronteras exactas. Cercanía temática no implica acuerdo político.</p></section>\n<aside class=\"sidebar\"><div class=\"aside-head\"><div class=\"eyebrow\" id=\"atlas-aside-kicker\">Elegí tu próxima parada</div><h2 id=\"atlas-aside-title\">Territorios por explorar</h2></div><div class=\"aside-body\" id=\"atlas-detail\"></div><section class=\"search-section\"><label for=\"atlas-search\">Buscar un proyecto</label><input id=\"atlas-search\" type=\"search\" placeholder=\"Dengue, alquileres o expediente…\"><div id=\"atlas-result-count\" class=\"small\" role=\"status\"></div><div class=\"results\" id=\"atlas-results\"></div></section></aside></div>\n<details class=\"method\"><summary>Cómo leer esta geografía</summary><p>Los puntos conservan las posiciones de UMAP (MiniLM multilingüe, 15 vecinos, semilla 17). Las costas se dibujan a partir de su distribución en el plano: no representan cantidad de trabajo, prioridad, calidad ni acuerdo político. Los ejes no tienen significado geográfico.</p><p>Diez nombres editoriales se apoyan en la revisión de ocho proyectos representativos por agrupación candidata. No todos los proyectos de un tema están juntos ni todos los de una zona hablan exactamente de lo mismo. Las Islas del calendario reúnen una tarea legislativa, no un único tema. Los sumarios ambiguos siguen visibles; el sector de referencias legales queda sin nombre temático.</p><p>Las firmas solo iluminan proyectos. Los vecinos del panel se calculan en el espacio semántico original, no por cercanía en este dibujo. “Sin firmas compartidas” excluye personas presentes en ambos expedientes; no afirma que nunca hayan colaborado.</p><p>Fuente: expedientes oficiales de la Legislatura. Atlas experimental de 2.206 proyectos de ley hasta el 14/10/2026. Incluye autorías externas al padrón. Los proyectos posteriores al corte se consultan en el listado; no se incorporan automáticamente a este mapa.</p></details><p id=\"atlas-status\" class=\"sr\" role=\"status\"></p>";
    mountAtlas(root,data);
  }catch(error){
    mounted.delete(root);
    root.innerHTML='<p class="note" role="status">No se pudo cargar el mapa. Podés consultar el listado de proyectos o volver a intentar.</p><button type="button">Volver a intentar</button>';
    root.querySelector('button').onclick=()=>renderAtlas(root);
  }finally{root.setAttribute('aria-busy','false');}
}
function mountAtlas(root,D){

const $=id=>root.querySelector('#atlas-'+id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n.toLocaleString('es-AR'),svg=d3.select(root.querySelector('#atlas-map')),world=svg.append('g'),sea=world.append('g'),terrain=world.append('g'),dots=world.append('g'),leaders=world.append('g'),labels=world.append('g'),visited=new Set();let zone=null,project=null,person='',unshared=true;
root.querySelector('.key').insertAdjacentHTML('beforeend','<span class="zone-key"><i></i>Zona seleccionada</span><span class="flag-key"><i></i>Sumario poco descriptivo</span>');
svg.insert('defs',':first-child').html('<pattern id="atlas-ocean-grid" width="60" height="60" patternUnits="userSpaceOnUse"><path d="M60 0H0V60" fill="none" stroke="#729b97" stroke-opacity=".13" stroke-width=".7"/></pattern>');
sea.append('rect').attr('x',-4000).attr('y',-4000).attr('width',9000).attr('height',9000).attr('fill','url(#atlas-ocean-grid)');
const contours=d3.contours().size([D.density.width,D.density.height]).thresholds([.015,.027,.045,.075,.115,.17])(D.density.values),path=d3.geoPath();
terrain.attr('transform',`scale(${1080/D.density.width},${840/D.density.height})`).selectAll('path').data(contours).join('path').attr('d',path).attr('fill',(d,i)=>['#f1e7cb','#e8dfbc','#d7d8ae','#bdc99d','#a8bb91','#94ae88'][i]).attr('stroke',(d,i)=>i===0?'#769488':'#a3ae88').attr('stroke-width',(d,i)=>i===0?.45:.22).attr('vector-effect','non-scaling-stroke');
const circles=dots.selectAll('circle').data(D.rows).join('circle').attr('cx',(d,i)=>D.points[i][0]).attr('cy',(d,i)=>D.points[i][1]).attr('r',1.8).attr('class',d=>d.flags.length?'point flagged':'point');
// Labels can move for legibility; project coordinates remain untouched.
const labelData=D.zones.map(z=>({...z,x:z.center[0],y:z.center[1]-23,w:Math.max(135,z.name.length*6.6),h:34}));
for(let pass=0;pass<160;pass++)for(let i=0;i<labelData.length;i++)for(let j=i+1;j<labelData.length;j++){const a=labelData[i],b=labelData[j],dx=a.x-b.x,dy=a.y-b.y,ox=(a.w+b.w)/2+12-Math.abs(dx),oy=56-Math.abs(dy);if(ox>0&&oy>0){if(oy<ox){a.y+=(dy>=0?1:-1)*oy*.3;b.y-=(dy>=0?1:-1)*oy*.3}else{a.x+=(dx>=0?1:-1)*ox*.3;b.x-=(dx>=0?1:-1)*ox*.3}}}
labelData.forEach(z=>{z.x=Math.max(z.w/2+20,Math.min(1060-z.w/2,z.x));z.y=Math.max(75,Math.min(735,z.y))});
leaders.selectAll('line').data(labelData).join('line').attr('class','region-leader').attr('x1',z=>z.center[0]).attr('y1',z=>z.center[1]).attr('x2',z=>z.x).attr('y2',z=>z.y);
const regionLabels=labels.selectAll('g').data(labelData).join('g').attr('class','carto-label').attr('transform',z=>`translate(${z.x},${z.y})`).attr('role','button').attr('tabindex',0).attr('aria-label',z=>`Explorar ${z.name}: ${z.subtitle}`).on('click',(ev,z)=>{ev.stopPropagation();travel(z.id)}).on('keydown',(ev,z)=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();travel(z.id)}});
regionLabels.append('rect').attr('x',z=>-z.w/2).attr('y',-17).attr('width',z=>z.w).attr('height',34).attr('rx',3);
regionLabels.append('text').attr('class','name').attr('text-anchor','middle').attr('y',-2).text(z=>z.name);
regionLabels.append('text').attr('class','sub').attr('text-anchor','middle').attr('y',10).text(z=>z.subtitle.toLocaleUpperCase('es-AR'));
labels.append('text').attr('x',D.uninterpreted_center[0]).attr('y',D.uninterpreted_center[1]).attr('text-anchor','middle').attr('fill','#425e53').attr('font-family','Georgia').attr('font-size',15).attr('font-style','italic').text('Referencias por descifrar').append('tspan').attr('x',D.uninterpreted_center[0]).attr('dy',15).attr('font-family','Arial').attr('font-style','normal').attr('font-size',9).text('AGRUPACIÓN SIN TEMA INTERPRETADO');
const zoom=d3.zoom().scaleExtent([.85,4]).filter(ev=>ev.type!=='wheel'&&!ev.button).on('zoom',ev=>world.attr('transform',ev.transform));svg.call(zoom).on('dblclick.zoom',null).on('click',(ev)=>{if(ev.defaultPrevented||ev.target.closest('.carto-label'))return;const [x,y]=d3.pointer(ev,world.node());let i=0,best=Infinity;D.points.forEach((p,j)=>{const d=(p[0]-x)**2+(p[1]-y)**2;if(d<best){best=d;i=j}});if(best<900)selectProject(i)});
$('plus').onclick=()=>svg.call(zoom.scaleBy,1.4);$('minus').onclick=()=>svg.call(zoom.scaleBy,1/1.4);$('reset').onclick=()=>{svg.call(zoom.transform,d3.zoomIdentity);zone=null;project=null;$('zone').value='';render()};
D.zones.forEach(z=>{const o=document.createElement('option');o.value=z.id;o.textContent=z.name;$('zone').append(o)});
D.people.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')).forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.nombre;$('person').append(o)});
$('zone').onchange=()=>{$('zone').value===''?$('reset').onclick():travel(Number($('zone').value))};$('person').onchange=()=>{person=$('person').value;render()};$('coauthors').onchange=render;$('labels').onchange=()=>{labels.attr('display',$('labels').checked?null:'none');leaders.attr('display',$('labels').checked?null:'none')};
function travel(id){zone=id;project=null;visited.add(id);$('zone').value=id;$('visited').textContent=visited.size+' / '+D.zones.length;const z=D.zones[id],pts=z.indices.map(i=>D.points[i]),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),k=Math.min(2.6,Math.max(1.15,Math.min(780/(Math.max(...xs)-Math.min(...xs)+140),600/(Math.max(...ys)-Math.min(...ys)+140))));svg.call(zoom.transform,d3.zoomIdentity.translate(540,420).scale(k).translate(-z.center[0],-z.center[1]));render();$('status').textContent='Explorando '+D.zones[id].name}
function selectProject(i){project=i;const t=d3.zoomTransform(svg.node()),p=D.points[i],q=t.apply(p);if(q[0]<80||q[0]>1000||q[1]<80||q[1]>760)svg.call(zoom.transform,d3.zoomIdentity.translate(540,420).scale(Math.max(1.5,t.k)).translate(-p[0],-p[1]));render();$('status').textContent='Proyecto seleccionado: '+D.rows[i].numero}
function paint(){const set=new Set(zone===null?[]:D.zones[zone].indices),near=new Set(project===null?[]:D.neighbors[project][unshared?'unshared':'distinct'].slice(0,5).map(n=>n.index));let count=0;
circles.attr('class',(p,i)=>{const signed=person&&(p.autor.id===person||($('coauthors').checked&&p.cofirmantes.some(x=>x.id===person)));if(signed)count++;return 'point'+(p.flags.length?' flagged':'')+(person&&!signed?' dim':'')+(set.has(i)?' zone':'')+(signed?' person':'')+(near.has(i)?' neighbor':'')+(i===project?' selected':'')}).attr('r',(p,i)=>i===project?5:near.has(i)?3.5:person&&(p.autor.id===person||($('coauthors').checked&&p.cofirmantes.some(x=>x.id===person)))?3:1.8);
if(project!==null)circles.filter((p,i)=>i===project).raise();regionLabels.attr('class',z=>'carto-label'+(z.id===zone?' active':'')+(visited.has(z.id)?' visited':''));$('person-count').textContent=person?fmt(count)+(count===1?' proyecto iluminado':' proyectos iluminados'):'';}
function buttons(indices){return '<div class="project-list">'+indices.map(i=>{const p=D.rows[i];return `<button data-project="${i}" class="${i===project?'chosen':''}"><small>${esc(p.numero)} · ${esc(p.autor.nombre)}</small>${esc(p.sumario)}</button>`}).join('')+'</div>'}
const people=new Map(D.people.map(p=>[p.id,p]));
function activity(indices,scope){
const include=$('coauthors').checked,counts=new Map();let external=0;
for(const i of new Set(indices)){const p=D.rows[i],signed=new Set([p.autor.id,...p.cofirmantes.map(c=>c.id)]);if(!people.has(p.autor.id))external++;for(const id of signed){if(!people.has(id))continue;const author=p.autor.id===id;if(!author&&!include)continue;const row=counts.get(id)||{id,author:0,coauthor:0,total:0};row[author?'author':'coauthor']++;row.total++;counts.set(id,row)}}
const rows=[...counts.values()].sort((a,b)=>b.total-a.total||people.get(a.id).nombre.localeCompare(people.get(b.id).nombre,'es')),top=rows.slice(0,5),max=top[0]?.total||1;
const title=include?'Más proyectos firmados':'Más autorías',where=scope==='zona'?'en esta zona':'en este entorno temático';
const basis=scope==='zona'?`${fmt(indices.length)} expedientes de la agrupación completa.`:`${fmt(indices.length)} expedientes: el seleccionado y sus 20 vecinos semánticos más próximos. La cercanía se calcula con los textos, no con la distancia del mapa.`;
return `<section class="activity" aria-label="Legisladores con más participación"><h3>${title} ${where}</h3><p class="small">${basis} ${include?'Cada expediente cuenta una vez por firmante.':'Se cuenta la autoría principal.'}</p>${top.length?'<div class="activity-list">'+top.map(r=>`<button data-person="${esc(r.id)}" aria-pressed="${person===r.id}" aria-label="Iluminar proyectos de ${esc(people.get(r.id).nombre)}: ${r.total} ${include?'proyectos firmados':'autorías'}" style="--share:${r.total/max*100}%"><span class="activity-name">${esc(people.get(r.id).nombre)}</span><strong>${fmt(r.total)}</strong><small>${fmt(r.author)} ${r.author===1?'autoría':'autorías'}${include?' · '+fmt(r.coauthor)+' '+(r.coauthor===1?'coautoría':'coautorías'):''}</small></button>`).join('')+'</div>':'<p class="small">Sin legisladores del padrón con participación en estos expedientes.</p>'}<p class="small">${rows.length>5?'Se muestran cinco. ':''}Empates ordenados por nombre. Seleccioná una persona para iluminar sus proyectos.${external?' '+fmt(external)+' '+(external===1?'expediente tiene':'expedientes tienen')+' autoría fuera del padrón.':''}</p></section>`;
}
function render(){paint();if(project!==null){const p=D.rows[project],nn=D.neighbors[project][unshared?'unshared':'distinct'].slice(0,5);$('aside-kicker').textContent='Una parada en el atlas';$('aside-title').textContent='Proyecto '+p.numero;$('detail').innerHTML=`<button class="back" id="atlas-back">← Volver a ${zone===null?'los territorios':'la zona'}</button><h3>${esc(p.sumario)}</h3><p>${esc(p.autor.nombre)}<br>${esc(p.fecha)}${!p.author_in_roster?' · Autoría fuera del padrón':''}</p><p><a href="${esc(p.url)}" target="_blank" rel="noopener">Abrir expediente oficial ↗</a></p>${p.flags.length?'<p>Sumario poco descriptivo: no alcanza para interpretar su tema con confianza.</p>':''}${activity([project,...D.semantic_neighborhoods[project].filter(i=>i!==project).slice(0,20)],'entorno')}<h3>Proyectos semánticamente cercanos</h3><p class="small">Calculados con los textos, fuera del mapa. Pueden incluir relaciones débiles.</p><label class="check"><input id="atlas-unshared" type="checkbox" ${unshared?'checked':''}>Sin firmas compartidas</label>${buttons(nn.map(n=>n.index))}`;$('back').onclick=()=>{project=null;render()};$('unshared').onchange=()=>{unshared=$('unshared').checked;render()};}
else if(zone!==null){const z=D.zones[zone];$('aside-kicker').textContent='Territorio explorado · '+(zone+1).toString().padStart(2,'0');$('aside-title').textContent=z.name;$('detail').innerHTML=`<p>${esc(z.description)}</p><span class="number">${fmt(z.indices.length)} EXPEDIENTES EN ESTA AGRUPACIÓN</span><p class="small">Nombre editorial provisional. La zona no reúne todos los proyectos de este tema.</p>${activity(z.indices,'zona')}<h3>Proyectos representativos</h3>${buttons(z.representatives.slice(0,5))}`;}
else{$('aside-kicker').textContent='Elegí tu próxima parada';$('aside-title').textContent='Territorios por explorar';$('detail').innerHTML='<p>Los puntos son proyectos. Las zonas son pistas para empezar el viaje.</p><div class="region-buttons">'+D.zones.map(z=>`<button data-zone="${z.id}">${visited.has(z.id)?'✓ ':''}${esc(z.name)}<small>${esc(z.subtitle)}</small></button>`).join('')+'</div>';$('detail').querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>travel(Number(b.dataset.zone)))}
$('detail').querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{person=b.dataset.person;$('person').value=person;render();$('status').textContent='Proyectos iluminados de '+people.get(person).nombre});$('detail').querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>selectProject(Number(b.dataset.project)));}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');$('search').oninput=()=>{const q=normalize($('search').value.trim());$('results').replaceChildren();$('result-count').textContent='';if(!q)return;const all=D.rows.map((p,i)=>({p,i})).filter(({p})=>normalize(p.numero+' '+p.sumario).includes(q));$('result-count').textContent=fmt(all.length)+(all.length===1?' resultado':' resultados')+(all.length>25?' · primeros 25':'');all.slice(0,25).forEach(({p,i})=>{const b=document.createElement('button');b.textContent=p.numero+' · '+p.sumario;b.onclick=()=>selectProject(i);$('results').append(b)})};render();

}
